{
  "gate_token": "ZC35nNOLDsAOJeoMgLai3A",
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unrolls a map of the ruined royal city.",
      "visual_description": "A windswept hilltop overlook at dusk; an ink-stained coated mapmaker with a brass compass spreads a vellum map showing broken spires and a distant bridge.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of obvious traps ahead.",
      "visual_description": "Close-up of an oil lamp held aloft, a single glowing eye inside the flame casting orange light across Mara's worried face.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "Tin Fox sniffs the wind near the castle gates.",
      "visual_description": "A small clockwork fox with blue glass eyes and a key-wind tail crouches before tall iron castle gates draped with torn royal banners.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "Glass Diver steps out of a cracked shop window.",
      "visual_description": "A figure in a clear diving helmet emerges from a fractured storefront pane, coat reflecting broken neon-blue city lights and falling glass shards.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "The team meets in a collapsed plaza fountain.",
      "visual_description": "A dry stone fountain in a moonlit plaza; the mapmaker, the clockwork fox, the oracle lamp, and the glass-helmeted rescuer gather around a chalk-drawn route.",
      "characters": ["mara_the_cartographer", "tin_fox", "oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "A sleeping official blocks the records office door.",
      "visual_description": "A plump bureaucrat slumped against a doorway, ledger book under his head as a pillow, stamped papers stuck to his sleeves, drool on official seals.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 7,
      "caption": "Mara lifts the keyring without waking him.",
      "visual_description": "The cartographer leans over the snoring official, two fingers pinching a brass keyring; the tin fox watches from the shadow of a filing cabinet.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "Armored patrols march past the cursed tower.",
      "visual_description": "From a low gutter view: clanking metal greaves stomp past in the foreground while a leaning black tower glows with purple cracks behind.",
      "characters": ["tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "The oracle lamp ignores the dragon rumor.",
      "visual_description": "A graffiti-scrawled wall depicting a scaly winged beast; the lamp's eye narrows skeptically while Mara tugs her coat tighter.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "Glass Diver slips through a tall mirror.",
      "visual_description": "A gilded ballroom mirror ripples like water; the helmeted rescuer half-submerged in its surface, coat trailing silver reflections.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "Inside the mirror, a magic door pulses.",
      "visual_description": "A corridor of floating mirror fragments; at its end, an arched door inscribed with rotating runes glows turquoise.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "Tin Fox solves the rune lock with a precise tap.",
      "visual_description": "Close shot of the clockwork fox's metal paw pressing a rune; sparks ricochet off the door, runes spinning into alignment.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "They find the captive in a banner-draped cell.",
      "visual_description": "A small stone cell hung with faded royal banners; the sleeping tax collector — yes, the same one — is curled on a cot, paperwork still stuck to him.",
      "characters": ["sleeping_tax_collector", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 14,
      "caption": "The rescue target was the dozing official all along.",
      "visual_description": "Mara raises an eyebrow at the lamp; the lamp's eye flares in apology; the tax collector snores serenely beneath a torn crest.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 15,
      "caption": "Frightened townspeople scatter as alarms ring.",
      "visual_description": "Distant silhouettes flee down a smoky avenue under clanging bell towers; the team carries the limp official between them, the fox running ahead.",
      "characters": ["mara_the_cartographer", "glass_diver", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "Armored patrols converge on the river road.",
      "visual_description": "Torchlight columns advance from three streets, helmets and pikes glinting; the lamp's beam picks a narrow alley exit toward the water.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "They sprint across the cracked stone bridge.",
      "visual_description": "A long arched bridge over black water at dawn, half its parapet collapsed; four figures and one bundled sleeper race toward the far bank as embers fall.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far shore, the official sleeps on.",
      "visual_description": "Pink dawn over reed marshes; Mara folds her map, the fox winds its own tail, the lamp dims to a candle-glow, and the tax collector snores against a milestone.",
      "characters": ["mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector", "glass_diver"]
    }
  ]
}

